chain customerId Customers;
if %found(Customers);
  // Use the retrieved customer
endif;

setll customerId Orders;
reade customerId Orders;
dow not %eof(Orders);
  // Process current order
  reade customerId Orders;
enddo;

dcl-f Orders usage(*input) keyed usropn;
if not %open(Orders);
  open Orders;
endif;
// Read and handle status
close Orders;

SELECT customer_id, SUM(amount) AS total
FROM app.orders WHERE status <> 'CANCELLED'
GROUP BY customer_id HAVING SUM(amount) > 1000;

SELECT c.id, o.id
FROM app.customer c LEFT JOIN app.orders o
  ON o.customer_id=c.id AND o.status='OPEN';

SELECT c.id FROM app.customer c
WHERE EXISTS (SELECT 1 FROM app.invoice i
 WHERE i.customer_id=c.id AND i.status='OVERDUE');

DECLARE c CURSOR FOR SELECT id FROM app.orders;
OPEN c;
-- FETCH, check SQLSTATE, process, repeat
CLOSE c;

SELECT id, customer_id,
 ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY created_at DESC, id DESC) AS rn
FROM app.orders;

